#!/usr/bin/env node
/**
 * marketnow-memory — persistent semantic memory for ANY AI agent.
 *
 * Single-file, zero-dependency MCP server + CLI (Node >= 18, stdlib only).
 * Works with Claude Code, Cursor, Codex CLI, Windsurf, Cline, Continue,
 * Aider, OpenCode, Goose, Amp and any MCP-compatible client.
 *
 * Storage: local JSON file (default ~/.marketnow-memory/memory.json,
 * override with MARKETNOW_MEMORY_HOME or --home). No cloud, no telemetry,
 * no API keys. Semantic search = local TF-IDF + cosine similarity.
 *
 * MCP mode (default):   node marketnow-memory.js            (stdio JSON-RPC)
 * CLI mode:             node marketnow-memory.js <command>  (see help)
 *
 * (c) 2026 AliceLabs LLC — MIT license. Part of MarketNow.
 */
'use strict';

const fs = require('fs');
const path = require('path');
const os = require('os');
const crypto = require('crypto');

const VERSION = '1.0.0';
const SERVER_NAME = 'marketnow-memory';
const PROTOCOL_VERSIONS = ['2025-06-18', '2025-03-26', '2024-11-05'];

/* ---------------------------------------------------------------- storage */

function homeDir() {
  if (process.env.MARKETNOW_MEMORY_HOME) return process.env.MARKETNOW_MEMORY_HOME;
  return path.join(os.homedir(), '.marketnow-memory');
}

function dbPath() { return path.join(homeDir(), 'memory.json'); }

function load() {
  const p = dbPath();
  try {
    const raw = fs.readFileSync(p, 'utf8');
    const d = JSON.parse(raw);
    if (!Array.isArray(d.memories)) d.memories = [];
    return d;
  } catch (_) {
    return { memories: [], created_at: new Date().toISOString() };
  }
}

function save(db) {
  const dir = homeDir();
  fs.mkdirSync(dir, { recursive: true });
  db.updated_at = new Date().toISOString();
  const p = dbPath();
  const tmp = p + '.tmp-' + process.pid;
  fs.writeFileSync(tmp, JSON.stringify(db, null, 2));   // atomic-ish write
  fs.renameSync(tmp, p);
}

function newId() {
  return 'mem-' + Date.now().toString(36) + '-' + crypto.randomBytes(3).toString('hex');
}

const TYPES = ['decision', 'rule', 'preference', 'fact'];

/* ------------------------------------------------- TF-IDF + cosine search */

const STOPWORDS = new Set(('a,an,and,are,as,at,be,been,but,by,can,do,does,for,from,had,has,have,' +
  'how,i,in,is,it,its,me,my,no,not,of,on,or,our,so,some,than,that,the,their,them,then,' +
  'there,these,they,this,to,too,us,very,was,we,were,what,when,which,who,why,will,with,' +
  'you,your,want,need,should,would,could').split(','));

function tokenize(text) {
  return String(text || '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .split(/\s+/)
    .filter((t) => t.length > 1 && !STOPWORDS.has(t));
}

// Map unseen query tokens to a known vocab token that starts with them
// (e.g. "postgres" -> "postgresql"). Returns the token itself if no match.
function mapToVocab(token, idf) {
  if (idf.has(token)) return token;
  let best = null;
  for (const key of idf.keys()) {
    if (key.startsWith(token) && (!best || key.length < best.length)) best = key;
  }
  return best || token;
}

function buildIndex(memories) {
  const docs = memories.map((m) => tokenize([m.content, m.topic, (m.tags || []).join(' ')].join(' ')));
  const df = new Map();
  docs.forEach((toks) => {
    new Set(toks).forEach((t) => df.set(t, (df.get(t) || 0) + 1));
  });
  const N = Math.max(1, memories.length);
  const idf = new Map();
  df.forEach((c, t) => idf.set(t, Math.log(1 + N / c)));
  return { docs, idf, N };
}

function vectorize(tokens, idf) {
  const tf = new Map();
  tokens.forEach((t) => tf.set(t, (tf.get(t) || 0) + 1));
  const v = new Map();
  tf.forEach((c, t) => {
    const w = (c / tokens.length) * (idf.get(t) || 1.5);
    v.set(t, w);
  });
  return v;
}

function cosine(a, b) {
  let dot = 0, na = 0, nb = 0;
  a.forEach((va, t) => { na += va * va; if (b.has(t)) dot += va * b.get(t); });
  b.forEach((vb) => { nb += vb * vb; });
  if (!na || !nb) return 0;
  return dot / Math.sqrt(na * nb);
}

function searchMemories(db, query, limit) {
  const memories = db.memories;
  if (!memories.length) return [];
  const idx = buildIndex(memories);
  const qTokens = tokenize(query).map((t) => mapToVocab(t, idx.idf));
  const qv = vectorize(qTokens, idx.idf);
  const scored = memories.map((m, i) => {
    const dv = vectorize(idx.docs[i], idx.idf);
    const sim = cosine(qv, dv);
    // recency & importance boosts (small, documented)
    const ageDays = (Date.now() - Date.parse(m.created_at || 0)) / 86400000;
    const recency = 1 / (1 + ageDays / 30);
    const importance = (typeof m.importance === 'number' ? m.importance : 3) / 5;
    const score = 0.7 * sim + 0.15 * recency + 0.15 * importance;
    return { m, score, sim };
  });
  scored.sort((a, b) => b.score - a.score);
  const hits = scored.filter((s) => s.sim > 0.01).slice(0, limit || 8);
  if (hits.length) return hits;

  // Lexical fallback: no token overlap at all (e.g. "package manager" vs
  // "pnpm, npm") — try case-insensitive substring on content/topic/tags.
  const raw = String(query || '').toLowerCase().trim();
  if (!raw) return [];
  const words = raw.split(/\s+/).filter((w) => w.length > 2 && !STOPWORDS.has(w));
  if (!words.length) return [];
  const lexical = [];
  memories.forEach((m) => {
    const hay = [m.content, m.topic, (m.tags || []).join(' ')].join(' ').toLowerCase();
    if (words.some((w) => hay.includes(w))) {
      lexical.push({ m, score: 0.3, sim: 0.3, lexical: true });
    }
  });
  return lexical.slice(0, limit || 8);
}

/* ------------------------------------------------------------- operations */

function op_add(db, params) {
  const content = String(params.content || '').trim();
  if (!content || content.length < 3) throw new Error('content is required (min 3 chars)');
  const type = TYPES.includes(params.type) ? params.type : 'fact';
  const topic = String(params.topic || 'general').trim().toLowerCase();
  const tags = Array.isArray(params.tags) ? params.tags.map(String).slice(0, 12) : [];
  const importance = Math.min(5, Math.max(1, Number(params.importance) || 3));
  const m = {
    id: newId(),
    type, topic, tags, content, importance,
    project: params.project ? String(params.project) : null,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  db.memories.push(m);
  save(db);
  return { stored: true, id: m.id, memory: m };
}

function op_search(db, params) {
  const q = String(params.query || '').trim();
  if (!q) throw new Error('query is required');
  const hits = searchMemories(db, q, Number(params.limit) || 8);
  return {
    query: q,
    total_memories: db.memories.length,
    hits: hits.map((h) => ({
      id: h.m.id, type: h.m.type, topic: h.m.topic, tags: h.m.tags,
      content: h.m.content, importance: h.m.importance,
      created_at: h.m.created_at,
      similarity: Number(h.sim.toFixed(3)),
    })),
  };
}

function op_bootstrap(db, params) {
  // Return the most useful context for a new session:
  // top rules+preferences by importance, plus optional query matches.
  const rules = db.memories
    .filter((m) => m.type === 'rule' || m.type === 'preference')
    .sort((a, b) => (b.importance || 3) - (a.importance || 3) || Date.parse(b.created_at) - Date.parse(a.created_at))
    .slice(0, Number(params.rules_limit) || 10);
  const recent = db.memories
    .slice()
    .sort((a, b) => Date.parse(b.created_at) - Date.parse(a.created_at))
    .slice(0, Number(params.recent_limit) || 10);
  let matches = [];
  if (params.query) {
    matches = searchMemories(db, params.query, Number(params.match_limit) || 5).map((h) => h.m);
  }
  return {
    total_memories: db.memories.length,
    rules_and_preferences: rules,
    recent: recent,
    query_matches: matches,
    hint: 'Load rules/preferences into your working context, then recall specifics with memory_search.',
  };
}

function op_profile(db) {
  const byType = {}, byTopic = {};
  db.memories.forEach((m) => {
    byType[m.type] = (byType[m.type] || 0) + 1;
    const t = m.topic || 'general';
    byTopic[t] = (byTopic[t] || 0) + 1;
  });
  const groups = {};
  db.memories.forEach((m) => {
    const t = m.topic || 'general';
    (groups[t] = groups[t] || []).push({ id: m.id, type: m.type, content: m.content, importance: m.importance, created_at: m.created_at });
  });
  return {
    total_memories: db.memories.length,
    by_type: byType,
    by_topic: byTopic,
    topics: groups,
    storage: dbPath(),
    updated_at: db.updated_at || null,
  };
}

function op_forget(db, params) {
  const before = db.memories.length;
  let removed = [];
  if (params.id) {
    const i = db.memories.findIndex((m) => m.id === params.id);
    if (i >= 0) removed.push(db.memories.splice(i, 1)[0]);
  } else if (params.query) {
    const hits = searchMemories(db, params.query, 50);
    const ids = new Set(hits.filter((h) => h.sim >= (params.min_similarity || 0.15)).map((h) => h.m.id));
    if (params.confirm) {
      removed = db.memories.filter((m) => ids.has(m.id));
      db.memories = db.memories.filter((m) => !ids.has(m.id));
    } else {
      return { dry_run: true, matched: hits.length, would_remove: hits.map((h) => ({ id: h.m.id, content: h.m.content, similarity: Number(h.sim.toFixed(3)) })), note: 'Re-run with confirm:true to actually delete.' };
    }
  } else {
    throw new Error('provide id or query');
  }
  if (removed.length) save(db);
  return { removed: removed.length, remaining: db.memories.length, before };
}

function op_clear(db, params) {
  if (params && params.confirm === true) {
    const n = db.memories.length;
    db.memories = [];
    save(db);
    return { cleared: true, removed: n, backup_note: 'Run memory_export before clearing if you need the data.' };
  }
  return { cleared: false, total: db.memories.length, note: 'Pass confirm:true to wipe ALL memories. This cannot be undone.' };
}

function op_status(db) {
  let st = 'ok';
  try { fs.statSync(dbPath()); } catch (_) { st = 'not-created-yet'; }
  return {
    ok: true,
    server: SERVER_NAME,
    version: VERSION,
    protocol: 'MCP (stdio, JSON-RPC 2.0)',
    storage: dbPath(),
    storage_status: st,
    total_memories: db.memories.length,
    last_write: db.updated_at || null,
    search_backend: 'local TF-IDF + cosine similarity',
    telemetry: 'none',
    network: 'none required — fully local',
  };
}

function op_export(db, params) {
  const fmt = params.format === 'markdown' ? 'markdown' : 'json';
  if (fmt === 'markdown') {
    const lines = ['# marketnow-memory export', '', `- Date: ${new Date().toISOString()}`, `- Total memories: ${db.memories.length}`, ''];
    const groups = {};
    db.memories.forEach((m) => { (groups[m.topic || 'general'] = groups[m.topic || 'general'] || []).push(m); });
    Object.keys(groups).sort().forEach((t) => {
      lines.push(`## Topic: ${t}`, '');
      groups[t].forEach((m) => {
        lines.push(`- **[${m.type}]** ${m.content} _(importance ${m.importance || 3}, ${m.created_at}, id ${m.id})_`);
      });
      lines.push('');
    });
    return { format: 'markdown', markdown: lines.join('\n'), total: db.memories.length };
  }
  return { format: 'json', data: db, total: db.memories.length };
}

/* ------------------------------------------------------------ MCP server */

const TOOLS = [
  {
    name: 'memory_bootstrap',
    description: 'Load relevant memories to bootstrap a new session: top rules and preferences by importance, plus recent memories and optional query matches. Call at session start.',
    inputSchema: {
      type: 'object',
      properties: {
        query: { type: 'string', description: 'Optional focus for semantic matches (e.g. current project)' },
        rules_limit: { type: 'number', description: 'Max rules/preferences to return (default 10)' },
        recent_limit: { type: 'number', description: 'Max recent memories to return (default 10)' },
        match_limit: { type: 'number', description: 'Max query matches to return (default 5)' },
      },
    },
  },
  {
    name: 'memory_search',
    description: 'Semantic search over stored memories (local TF-IDF cosine similarity, boosted by recency and importance).',
    inputSchema: {
      type: 'object',
      properties: {
        query: { type: 'string', description: 'What to look for' },
        limit: { type: 'number', description: 'Max results (default 8)' },
      },
      required: ['query'],
    },
  },
  {
    name: 'memory_add',
    description: 'Store a memory: a decision, rule, preference or fact worth remembering across sessions.',
    inputSchema: {
      type: 'object',
      properties: {
        content: { type: 'string', description: 'The memory itself, e.g. "We use pnpm, never npm"' },
        type: { type: 'string', enum: TYPES, description: 'decision | rule | preference | fact' },
        topic: { type: 'string', description: 'Grouping topic, e.g. "tooling", "auth" (default general)' },
        tags: { type: 'array', items: { type: 'string' }, description: 'Up to 12 tags' },
        importance: { type: 'number', description: '1-5 (default 3)' },
        project: { type: 'string', description: 'Optional project name' },
      },
      required: ['content'],
    },
  },
  {
    name: 'memory_profile',
    description: 'Show the full memory profile grouped by topics, with counts by type and topic. Use when the user asks "what do you remember about me?".',
    inputSchema: { type: 'object', properties: {} },
  },
  {
    name: 'memory_forget',
    description: 'Remove specific memories by id, or by semantic query (dry-run by default; pass confirm:true to delete).',
    inputSchema: {
      type: 'object',
      properties: {
        id: { type: 'string', description: 'Exact memory id to remove' },
        query: { type: 'string', description: 'Semantic query; matched memories are removed when confirm:true' },
        min_similarity: { type: 'number', description: 'Similarity threshold for query removal (default 0.15)' },
        confirm: { type: 'boolean', description: 'Actually delete (without it: dry-run preview)' },
      },
    },
  },
  {
    name: 'memory_clear',
    description: 'Wipe ALL memories. DANGER ZONE: requires confirm:true. Suggest memory_export first.',
    inputSchema: {
      type: 'object',
      properties: { confirm: { type: 'boolean', description: 'Must be true to wipe' } },
    },
  },
  {
    name: 'memory_status',
    description: 'Service health: storage path, counts, search backend, version. No parameters.',
    inputSchema: { type: 'object', properties: {} },
  },
  {
    name: 'memory_export',
    description: 'Export all memories as JSON or Markdown for backup or portability.',
    inputSchema: {
      type: 'object',
      properties: { format: { type: 'string', enum: ['json', 'markdown'], description: 'Export format (default json)' } },
    },
  },
];

const OPS = {
  memory_bootstrap: op_bootstrap,
  memory_search: op_search,
  memory_add: op_add,
  memory_profile: op_profile,
  memory_forget: op_forget,
  memory_clear: op_clear,
  memory_status: op_status,
  memory_export: op_export,
};

function handleToolCall(name, args) {
  const fn = OPS[name];
  if (!fn) throw new Error('Unknown tool: ' + name);
  return fn(load(), args || {});
}

function handleMessage(msg) {
  // notification (no id) — nothing to reply
  if (msg.id === undefined || msg.id === null) return null;

  const { id, method, params } = msg;
  if (method === 'initialize') {
    const wanted = params && params.protocolVersion;
    const proto = PROTOCOL_VERSIONS.includes(wanted) ? wanted : PROTOCOL_VERSIONS[0];
    return { jsonrpc: '2.0', id, result: { protocolVersion: proto, capabilities: { tools: {} }, serverInfo: { name: SERVER_NAME, version: VERSION } } };
  }
  if (method === 'ping') return { jsonrpc: '2.0', id, result: {} };
  if (method === 'tools/list') return { jsonrpc: '2.0', id, result: { tools: TOOLS } };
  if (method === 'tools/call') {
    const tname = params && params.name;
    try {
      const out = handleToolCall(tname, params.arguments);
      return { jsonrpc: '2.0', id, result: { content: [{ type: 'text', text: JSON.stringify(out, null, 2) }] } };
    } catch (e) {
      return { jsonrpc: '2.0', id, result: { content: [{ type: 'text', text: 'Error: ' + e.message }], isError: true } };
    }
  }
  if (method === 'resources/list') return { jsonrpc: '2.0', id, result: { resources: [] } };
  if (method === 'prompts/list') return { jsonrpc: '2.0', id, result: { prompts: [] } };
  return { jsonrpc: '2.0', id, error: { code: -32601, message: 'Method not found: ' + method } };
}

function runServer() {
  let buf = '';
  process.stdin.setEncoding('utf8');
  process.stdin.on('data', (chunk) => {
    buf += chunk;
    let nl;
    while ((nl = buf.indexOf('\n')) >= 0) {
      const line = buf.slice(0, nl).trim();
      buf = buf.slice(nl + 1);
      if (!line) continue;
      let msg;
      try { msg = JSON.parse(line); } catch (_) { continue; }
      try {
        const res = handleMessage(msg);
        if (res) process.stdout.write(JSON.stringify(res) + '\n');
      } catch (e) {
        if (msg.id !== undefined) {
          process.stdout.write(JSON.stringify({ jsonrpc: '2.0', id: msg.id, error: { code: -32603, message: String(e.message || e) } }) + '\n');
        }
      }
    }
  });
  process.stdin.on('end', () => process.exit(0));
}

/* ------------------------------------------------------------------- CLI */

const HELP = `marketnow-memory v${VERSION} — persistent semantic memory for any AI agent

MCP mode (default):
  node marketnow-memory.js                       stdio JSON-RPC server

CLI mode:
  node marketnow-memory.js add "content" [--type rule] [--topic tooling] [--importance 4] [--tag a --tag b]
  node marketnow-memory.js search "query" [--limit 8]
  node marketnow-memory.js profile
  node marketnow-memory.js bootstrap [--query "project"] [--json]
  node marketnow-memory.js forget --id <id> | --query "text" [--confirm]
  node marketnow-memory.js clear --confirm
  node marketnow-memory.js status
  node marketnow-memory.js export [--format json|markdown]

Storage: ${dbPath()}
Override with MARKETNOW_MEMORY_HOME=/some/dir (useful for tests / multi-profile).`;

function runCli(argv) {
  const [cmd, ...rest] = argv;
  const flags = {};
  const positional = [];
  for (let i = 0; i < rest.length; i++) {
    const a = rest[i];
    if (a.startsWith('--')) {
      const key = a.slice(2);
      const next = rest[i + 1];
      if (next !== undefined && !next.startsWith('--')) { flags[key] = next; i++; }
      else flags[key] = true;
    } else positional.push(a);
  }
  const db = load();
  switch (cmd) {
    case 'help': case '--help': case '-h':
      console.log(HELP); break;
    case 'add': {
      const content = positional.join(' ');
      const out = op_add(db, {
        content, type: flags.type, topic: flags.topic,
        importance: Number(flags.importance) || 3,
        tags: Array.isArray(flags.tag) ? flags.tag : (flags.tag ? [flags.tag] : undefined),
      });
      console.log('stored:', out.id);
      break;
    }
    case 'search': {
      const out = op_search(db, { query: positional.join(' '), limit: Number(flags.limit) || 8 });
      out.hits.forEach((h, i) => console.log(`${i + 1}. [${h.type}] ${h.content}  (sim ${h.similarity})`));
      if (!out.hits.length) console.log('no matches');
      break;
    }
    case 'bootstrap': {
      const out = op_bootstrap(db, { query: flags.query, match_limit: 5 });
      console.log(flags.json ? JSON.stringify(out, null, 2) : JSON.stringify(out, null, 2));
      break;
    }
    case 'profile': console.log(JSON.stringify(op_profile(db), null, 2)); break;
    case 'status': console.log(JSON.stringify(op_status(db), null, 2)); break;
    case 'export': {
      const out = op_export(db, { format: flags.format || 'json' });
      console.log(out.format === 'markdown' ? out.markdown : JSON.stringify(out.data, null, 2));
      break;
    }
    case 'forget': {
      const out = op_forget(db, { id: flags.id, query: flags.query, confirm: flags.confirm === true });
      console.log(JSON.stringify(out, null, 2));
      break;
    }
    case 'clear': {
      const out = op_clear(db, { confirm: flags.confirm === true });
      console.log(JSON.stringify(out, null, 2));
      break;
    }
    default:
      console.error('unknown command: ' + cmd + '\n');
      console.log(HELP);
      process.exit(1);
  }
}

if (require.main === module) {
  if (process.argv.length > 2) runCli(process.argv.slice(2));
  else runServer();
}

module.exports = {
  VERSION, SERVER_NAME, TOOLS, handleMessage, handleToolCall,
  op_add, op_search, op_profile, op_bootstrap, op_forget, op_clear, op_status, op_export,
  load, save, dbPath, homeDir,
};

