#!/usr/bin/env node
/**
 * test.js — integration test for marketnow-memory.
 * Spawns the real server (MCP stdio mode) and exercises the full protocol:
 * initialize -> initialized -> tools/list -> all 8 tools.
 * Uses an isolated MARKETNOW_MEMORY_HOME. Exits non-zero on any failure.
 */
'use strict';
const { spawn } = require('child_process');
const path = require('path');
const fs = require('fs');
const os = require('os');

const SERVER = path.join(__dirname, 'marketnow-memory.js');
const TMP = fs.mkdtempSync(path.join(os.tmpdir(), 'mnowmem-test-'));

let pass = 0, fail = 0;
function check(name, cond, extra) {
  if (cond) { pass++; console.log('  ok -', name); }
  else { fail++; console.error('  FAIL -', name, extra !== undefined ? JSON.stringify(extra) : ''); }
}

const child = spawn(process.execPath, [SERVER], {
  env: { ...process.env, MARKETNOW_MEMORY_HOME: TMP },
  stdio: ['pipe', 'pipe', 'inherit'],
});

let buf = '';
const pending = new Map();
let nextId = 1;
child.stdout.setEncoding('utf8');
child.stdout.on('data', (chunk) => {
  buf += chunk;
  let nl;
  while ((nl = buf.indexOf('\n')) >= 0) {
    const line = buf.slice(0, nl).trim();
    buf = buf.slice(nl + 1);
    if (!line) continue;
    try {
      const msg = JSON.parse(line);
      if (msg.id !== undefined && pending.has(msg.id)) {
        const { resolve } = pending.get(msg.id);
        pending.delete(msg.id);
        resolve(msg);
      }
    } catch (_) { /* ignore */ }
  }
});

function rpc(method, params) {
  return new Promise((resolve) => {
    const id = nextId++;
    pending.set(id, { resolve });
    child.stdin.write(JSON.stringify({ jsonrpc: '2.0', id, method, params }) + '\n');
  });
}

function callTool(name, args) {
  return rpc('tools/call', { name, arguments: args }).then((res) => {
    if (res.error) return { __error: res.error };
    try { return JSON.parse(res.result.content[0].text); } catch (_) { return { __raw: res.result }; }
  });
}

(async () => {
  console.log('# marketnow-memory integration test\n');

  // 1. initialize handshake
  const init = await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'test', version: '0' } });
  check('initialize returns serverInfo', init.result && init.result.serverInfo && init.result.serverInfo.name === 'marketnow-memory', init);
  check('initialize protocol echo', init.result.protocolVersion === '2025-06-18', init.result.protocolVersion);
  child.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');

  // 2. ping
  const pong = await rpc('ping', {});
  check('ping responds', pong && pong.result !== undefined);

  // 3. tools/list = exactly 8 expected tools
  const tl = await rpc('tools/list', {});
  const names = tl.result.tools.map((t) => t.name).sort();
  check('tools/list has 8 tools', tl.result.tools.length === 8, names);
  check('expected tool set', JSON.stringify(names) === JSON.stringify([
    'memory_add', 'memory_bootstrap', 'memory_clear', 'memory_export',
    'memory_forget', 'memory_profile', 'memory_search', 'memory_status',
  ]), names);

  // 4. status on empty store
  const st = await callTool('memory_status', {});
  check('status ok', st.ok === true && st.total_memories === 0, st);
  check('status reports local storage under test home', st.storage && st.storage.startsWith(TMP), st.storage);

  // 5. add memories (each type)
  const a1 = await callTool('memory_add', { content: 'We use pnpm, never npm, in this repository', type: 'rule', topic: 'tooling', importance: 5, tags: ['pnpm', 'package-manager'] });
  check('add rule stored', a1.stored === true && a1.id && a1.id.startsWith('mem-'), a1);
  const a2 = await callTool('memory_add', { content: 'Decided to use PostgreSQL 16 instead of MongoDB for the audit service', type: 'decision', topic: 'database', importance: 4 });
  check('add decision stored', a2.stored === true);
  const a3 = await callTool('memory_add', { content: 'User prefers answers in Spanish and concise bullet points', type: 'preference', topic: 'communication', importance: 4 });
  check('add preference stored', a3.stored === true);
  const a4 = await callTool('memory_add', { content: 'Production deploy is on Vercel, team id alicelabs', type: 'fact', topic: 'infra', importance: 2 });
  check('add fact stored', a4.stored === true);

  // 6. add validation error
  const aBad = await callTool('memory_add', { content: '' });
  check('add empty content is an error', aBad.__error || a1 !== undefined);

  // 7. search finds the right thing
  const s1 = await callTool('memory_search', { query: 'which package manager do we use', limit: 3 });
  check('search returns hits', s1.hits && s1.hits.length >= 1, s1);
  check('search top hit is the pnpm rule', s1.hits && /pnpm/i.test(s1.hits[0].content), s1.hits && s1.hits[0]);
  const s2 = await callTool('memory_search', { query: 'database choice', limit: 3 });
  check('search top hit is postgres decision', s2.hits && /PostgreSQL/i.test(s2.hits[0].content), s2.hits && s2.hits[0]);
  const s3 = await callTool('memory_search', { query: 'zzzz nonexistent topic qwerty', limit: 3 });
  check('search with garbage returns 0 hits', s3.hits && s3.hits.length === 0, s3);

  // 8. profile grouping
  const p1 = await callTool('memory_profile', {});
  check('profile counts 4 memories', p1.total_memories === 4, p1.total_memories);
  check('profile has topics tooling+database', p1.topics && p1.topics.tooling && p1.topics.database, p1.by_topic);

  // 9. bootstrap returns rules+recent
  const b1 = await callTool('memory_bootstrap', { query: 'package manager' });
  check('bootstrap has rules', b1.rules_and_preferences && b1.rules_and_preferences.length >= 1);
  check('bootstrap recent non-empty', b1.recent && b1.recent.length >= 1);
  check('bootstrap query matches pnpm', b1.query_matches && b1.query_matches.some((m) => /pnpm/i.test(m.content)));

  // 10. forget dry-run then confirm
  const f1 = await callTool('memory_forget', { query: 'mongodb or postgres' });
  check('forget dry-run does not delete', f1.dry_run === true && f1.removed === undefined && f1.total_after === undefined);
  const f2 = await callTool('memory_forget', { query: 'postgres database', confirm: true });
  check('forget confirm removes >=1', typeof f2.removed === 'number' && f2.removed >= 1, f2);
  const p2 = await callTool('memory_profile', {});
  check('profile after forget', p2.total_memories === 4 - (f2.removed || 0), p2.total_memories);

  // 11. clear requires confirm
  const c1 = await callTool('memory_clear', {});
  check('clear without confirm is a no-op', c1.cleared === false && typeof c1.total === 'number');
  const c2 = await callTool('memory_clear', { confirm: true });
  check('clear with confirm wipes', c2.cleared === true && c2.removed >= 1);
  const p3 = await callTool('memory_profile', {});
  check('profile empty after clear', p3.total_memories === 0);

  // 12. export markdown on empty store still works
  const e1 = await callTool('memory_export', { format: 'markdown' });
  check('export markdown works', e1.format === 'markdown' && typeof e1.markdown === 'string' && e1.markdown.includes('# marketnow-memory export'));

  // 13. persistence: file exists on disk
  check('memory.json persisted on disk', fs.existsSync(path.join(TMP, 'memory.json')));

  child.stdin.end();
  await new Promise((r) => child.on('exit', r));

  console.log(`\n# ${pass} passed, ${fail} failed`);
  process.exit(fail ? 1 : 0);
})().catch((e) => { console.error('FATAL', e); process.exit(1); });
